    if(messages[value])return messages[value];
    if(value.startsWith('আপিল: '))return 'Appeal: '+value.slice('আপিল: '.length);
    if(value.startsWith('ফাইলটি '))return 'File '+value.slice('ফাইলটি '.length);
    if(value.startsWith('–কে জবাব দিচ্ছ'))return 'Replying to '+value.slice(1);
    const count=value.match(/^([0-9০-৯,.]+)\s*(জন সাবস্ক্রাইবার|টি ভিডিও|টি মন্তব্য|ভিউ|লাইক|মন্তব্য|ঘণ্টা|দিন|মিনিট)(.*)$/);
    if(count){const unit={'জন সাবস্ক্রাইবার':'subscribers','টি ভিডিও':'videos','টি মন্তব্য':'comments','ভিউ':'views','লাইক':'likes','মন্তব্য':'comments','ঘণ্টা':'hours','দিন':'days','মিনিট':'minutes'}[count[2]]||count[2];return count[1]+' '+unit+count[3];}
    const ago=value.match(/^([0-9০-৯,.]+) (মিনিট আগে|ঘণ্টা আগে|দিন আগে)$/);if(ago)return ago[1]+' '+({'মিনিট আগে':'minutes ago','ঘণ্টা আগে':'hours ago','দিন আগে':'days ago'}[ago[2]]);
